test('every creature faces the way it is actually moving', () => {
  for (const id of Object.keys(SPECIES)) for (const dir of [-1, 1]) {
    const g = game({ r: 8 })
    const sp = SPECIES[id]
    const x = 700, y = Math.min(150, floorAt(g.world, x) - 40)
    const c = addCreature(g, id, x, y, (sp.rMin + sp.rMax) / 2)
    g.player.x = 100; g.player.y = 12
    c.vx = dir * 20; c.vy = 0; c.face = -dir // start facing the wrong way
    step(g, idle, 1 / 30)
    if (Math.abs(c.vx) > 2) assert.equal(c.face, dir, `${id} moving ${dir > 0 ? 'right' : 'left'} faces ${c.face > 0 ? 'right' : 'left'}`)
  }
})

test('schools and patrollers face their direction of travel', () => {
  const g = game()
  const a = addCreature(g, 'sardine', 700, 100, 1.8); a.dir = -1; a.face = -1
  const b = addCreature(g, 'sardine', 740, 100, 1.8); b.dir = 1; b.face = 1
  g.player.x = 100; g.player.y = 12
  for (let i = 0; i < 120; i++) {
    step(g, idle, 1 / 30)
    if (Math.abs(a.vx) > 4) assert.equal(Math.sign(a.vx), a.face, 'sardine a faces against its motion')
    if (Math.abs(b.vx) > 4) assert.equal(Math.sign(b.vx), b.face, 'sardine b faces against its motion')
  }
})

